'       TO_CHAR(',
'           SUM(INTERNACOES_2025),',
'           ''FM999G999G999G990'',',
'           ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'       ) AS valor',
'FROM ADMIN.V_DASHBOARD_REGIOES_SAUDE',
'',
'UNION ALL',
'',
'SELECT ''Leitos SUS'',',
'       TO_CHAR(',
'           SUM(TOTAL_LEITOS_SUS),',
'           ''FM999G999G999G990'',',
'           ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'       )',
'FROM ADMIN.V_DASHBOARD_REGIOES_SAUDE',
'',
'UNION ALL',
'',
'SELECT ''UTIs SUS'',',
'       TO_CHAR(',
'           SUM(TOTAL_UTI_SUS),',
'           ''FM999G999G999G990'',',
'           ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'       )',
'FROM ADMIN.V_DASHBOARD_REGIOES_SAUDE',
'',
'UNION ALL',
'',
'SELECT ''Cobertura de UTIs SUS'',',
'       TO_CHAR(',
'           ROUND(AVG(UTIS_SUS_POR_100K_HAB), 1),',
'           ''FM990D0'',',
'           ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'       ) || '' / 100 mil hab.''',
'FROM ADMIN.V_DASHBOARD_REGIOES_SAUDE',
'',
'UNION ALL',
'',
unistr('SELECT ''Popula\00E7\00E3o analisada'','),
'       TO_CHAR(',
