'           ''FM999G999G999G990'',',
'           ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'       )',
'FROM ADMIN.V_DASHBOARD_REGIOES_SAUDE',
'',
'UNION ALL',
'',
'SELECT ''Leitos existentes'',',
'       TO_CHAR(',
'           SUM(TOTAL_LEITOS_EXISTENTES),',
'           ''FM999G999G999G990'',',
'           ''NLS_NUMERIC_CHARACTERS='''',.''''''',
'       )',
'FROM ADMIN.V_DASHBOARD_REGIOES_SAUDE'))
